use std::collections::HashMap;
use std::sync::OnceLock;

use crate::ast::Mode;

#[allow(clippy::enum_variant_names)]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub(crate) enum SymbolGroup {
    AccentTokenGroup,
    BinaryGroup,
    CloseGroup,
    InnerGroup,
    MathOrdGroup,
    OperatorTokenGroup,
    OpenGroup,
    PunctuationGroup,
    RelationGroup,
    SpacingGroup,
    TextOrdGroup,
}

#[derive(Clone, Debug)]
pub(crate) struct SymbolSpec {
    pub(crate) group: SymbolGroup,
    pub(crate) replacement: String,
}

pub(crate) struct SymbolRegistry {
    pub(crate) math: HashMap<String, SymbolSpec>,
    pub(crate) text: HashMap<String, SymbolSpec>,
}

impl SymbolRegistry {
    fn new() -> Self {
        SymbolRegistry {
            math: HashMap::new(),
            text: HashMap::new(),
        }
    }

    fn define_symbol(
        &mut self,
        mode: Mode,
        group: SymbolGroup,
        replacement: &str,
        name: &str,
        accept_unicode: bool,
    ) {
        let table = if mode == Mode::Math {
            &mut self.math
        } else {
            &mut self.text
        };
        let spec = SymbolSpec {
            group,
            replacement: replacement.to_string(),
        };
        table.insert(name.to_string(), spec.clone());
        if accept_unicode && !replacement.is_empty() {
            table.insert(replacement.to_string(), spec);
        }
    }
}

fn codepoint_string(codepoint: u32) -> String {
    char::from_u32(codepoint).unwrap().to_string()
}

